"""Bounded cross-thread audio mailbox with at most one outstanding wakeup."""
import asyncio
import ctypes
import threading
from collections import deque


class AudioMailbox:
    def __init__(self, loop, capacity, native_queue=None):
        if not 1 <= capacity <= 256:
            raise ValueError("invalid audio mailbox capacity")
        self.loop = loop
        self.ready = asyncio.Event()
        self._capacity = capacity
        self._native = native_queue
        self._chunks = deque(maxlen=capacity)
        self._lock = threading.Lock()
        self._notified = False
        self._closed = False
        self._dropped = 0
        self._wakeups = 0

    def push_pointer(self, pointer, length):
        if not pointer or not 0 < length <= 65536:
            return False
        with self._lock:
            if self._closed:
                return False
            if self._native is not None:
                if self._native.push_pointer(pointer, length) < 0:
                    self._dropped += 1
                    return False
            else:
                if len(self._chunks) == self._capacity:
                    self._dropped += 1
                self._chunks.append(ctypes.string_at(pointer, length))
            if not self._notified:
                self._notified = True
                try:
                    self.loop.call_soon_threadsafe(self.ready.set)
                    self._wakeups += 1
                except RuntimeError:
                    self._notified = False
                    return False
            return True

    def accept_result(self, result_ptr, _user_data):
        if result_ptr:
            result = result_ptr.contents
            self.push_pointer(result.data, result.size)

    def pop(self):
        # Only the consumer event loop calls pop. Reset the event and producer
        # notification state under the same lock to avoid lost wakeups.
        with self._lock:
            if self._closed:
                return None
            packet = self._native.pop() if self._native is not None else (
                self._chunks.popleft() if self._chunks else None
            )
            if packet is None:
                self.ready.clear()
                self._notified = False
            return packet

    @property
    def closed(self):
        with self._lock:
            return self._closed

    @property
    def dropped(self):
        with self._lock:
            return self._dropped + (self._native.dropped if self._native is not None else 0)

    @property
    def wakeups(self):
        with self._lock:
            return self._wakeups

    def close(self):
        # Called on the consumer loop. A native callback can finish in parallel,
        # but it cannot access the freed queue or wake a replacement session.
        with self._lock:
            if self._closed:
                return
            self._closed = True
            if self._native is not None:
                self._dropped += self._native.dropped
                self._native.close()
                self._native = None
            self._chunks.clear()
        self.ready.set()
